"""HighQ Windows offers generated by Adrian@nordicaaluminum are shown as erp@oraglass.us."""

import logging

from storage import load_orders, load_quotes, load_users, save_customers, save_orders, save_quotes, save_users
from tests.conftest import login, write_user


ADRIAN = 'Adrian@nordicaaluminum.com'
ERP = 'erp@oraglass.us'


def _users(include_erp=True):
    users = {
        ADRIAN: {'email': ADRIAN, 'name': 'Adrian', 'role': 'customer', 'active': True},
        'other@oraglass.us': {'email': 'other@oraglass.us', 'name': 'Other', 'role': 'admin', 'active': True},
    }
    if include_erp:
        users[ERP] = {'email': ERP, 'name': 'ERP', 'role': 'admin', 'active': True}
    save_users(users)


def _records():
    save_customers({
        'highq-windows': {'id': 'highq-windows', 'name': 'HighQ Windows', 'tier': 'T2', 'status': 'active'},
        'other-glass': {'id': 'other-glass', 'name': 'Other Glass', 'tier': 'T2', 'status': 'active'},
    })
    save_quotes([
        {
            'id': 1, 'user': ADRIAN, 'company': 'highq windows', 'customer_id': 'highq-windows',
            'project': 'Lobby', 'total': 100, 'date': '2026-01-02', 'status': 'sent', 'tier': 'T2',
            'items': [{'total': 100}],
        },
        {
            'id': 2, 'user': 'OTHER@oraglass.us', 'company': 'HighQ Windows Inc.', 'customer_id': 'highq-windows',
            'project': 'Keep', 'total': 40, 'date': '2026-01-03', 'status': 'draft',
        },
        {
            'id': 3, 'user': ADRIAN, 'company': 'Other Glass', 'customer_id': 'other-glass',
            'project': 'Elsewhere', 'total': 8, 'date': '2026-01-04', 'status': 'draft',
        },
    ])
    save_orders([
        {
            'id': 9, 'quote_id': 1, 'company': 'HighQ Windows', 'customer_id': 'highq-windows',
            'approved_by': 'adrian@nordicaaluminum.ca', 'approved_at': '2026-01-05T00:00:00+00:00',
            'status': 'approved', 'total': 100, 'date': '2026-01-05',
            'changelog': [{'at': '2026-01-06', 'user': ADRIAN, 'changes': [{'field': 'notes', 'old': '', 'new': 'ok'}]}],
        },
        {
            'id': 10, 'quote_id': 1, 'company': 'HighQ Windows', 'customer_id': 'highq-windows',
            'approved_by': 'staff@oraglass.us', 'status': 'approved', 'total': 100,
        },
        {
            'id': 11, 'quote_id': 3, 'company': 'Other Glass', 'customer_id': 'other-glass',
            'approved_by': ADRIAN, 'status': 'approved', 'total': 8,
        },
    ])


def test_reassigns_only_the_creator_fields_and_is_idempotent(data_dir, caplog):
    import highq_owners
    _users()
    _records()
    with caplog.at_level(logging.INFO, logger='ora_glass.highq'):
        first = highq_owners.reassign_quote_owners()
    assert first == {'quotes': 1, 'orders': 1, 'skipped': False}
    assert 'reassigned 1 quote(s) and 1 order(s)' in caplog.text
    quotes = {row['id']: row for row in load_quotes()}
    assert quotes[1]['user'] == ERP
    assert quotes[1]['total'] == 100
    assert quotes[1]['date'] == '2026-01-02'
    assert quotes[1]['status'] == 'sent'
    assert quotes[1]['project'] == 'Lobby'
    assert quotes[2]['user'] == 'OTHER@oraglass.us'
    assert quotes[3]['user'] == ADRIAN
    orders = {row['id']: row for row in load_orders()}
    assert orders[9]['approved_by'] == ERP
    assert orders[9]['approved_at'] == '2026-01-05T00:00:00+00:00'
    assert orders[9]['status'] == 'approved'
    assert orders[9]['total'] == 100
    assert orders[9]['changelog'] == [{
        'at': '2026-01-06', 'user': ADRIAN, 'changes': [{'field': 'notes', 'old': '', 'new': 'ok'}],
    }]
    assert orders[10]['approved_by'] == 'staff@oraglass.us'
    assert orders[11]['approved_by'] == ADRIAN
    second = highq_owners.reassign_quote_owners()
    assert second == {'quotes': 0, 'orders': 0, 'skipped': False}
    assert load_users()[ERP]['email'] == ERP
    assert ADRIAN in load_users()


def test_skips_when_the_erp_user_does_not_exist(data_dir, caplog):
    import highq_owners
    _users(include_erp=False)
    _records()
    with caplog.at_level(logging.WARNING, logger='ora_glass.highq'):
        result = highq_owners.reassign_quote_owners()
    assert result == {'quotes': 0, 'orders': 0, 'skipped': True}
    assert 'does not exist' in caplog.text
    assert load_quotes()[0]['user'] == ADRIAN
    assert ERP not in load_users()
    assert load_orders()[0]['approved_by'] == 'adrian@nordicaaluminum.ca'


def test_startup_shows_the_new_owner_in_quote_history(client, data_dir):
    write_user('admin@oraglass.us', 'admin')
    users = load_users()
    users[ERP] = {'email': ERP, 'name': 'ERP', 'role': 'admin', 'active': True, 'password_hash': users['admin@oraglass.us']['password_hash']}
    users[ADRIAN] = {'email': ADRIAN, 'name': 'Adrian', 'role': 'customer', 'active': True}
    save_users(users)
    save_customers({'highq-windows': {'id': 'highq-windows', 'name': 'Highq Windows', 'tier': 'T2', 'status': 'active'}})
    save_quotes([{
        'id': 4, 'user': 'adrian@nordicaaluminum.com', 'company': 'Highq Windows',
        'customer_id': 'highq-windows', 'project': 'Front', 'items': [{'name': 'Lite', 'total': 12}],
        'currency': 'usd', 'type': 'sqf', 'tier': 'T2', 'date': '2026-02-01', 'status': 'draft',
    }])
    assert login(client, 'admin@oraglass.us').status_code == 302
    page = client.get('/quote-history')
    assert page.status_code == 200
    listed = client.get('/api/quotes').get_json()
    assert listed[0]['user'] == ERP
    assert listed[0]['project'] == 'Front'
    assert listed[0]['items'][0]['total'] == 12
    assert b'quote.user' in page.data
